<!doctype html><html><head><meta charset="utf-8"><style>body{font-family:Arial;color:#172033}.wrap{border:1px solid #cbd5e1;padding:28px}.head{text-align:center;border-bottom:2px solid #0f766e;padding-bottom:15px}.head h1{color:#0f766e;margin:0}.row{margin-top:18px;border-bottom:1px solid #e2e8f0;padding:10px 0}.label{display:inline-block;width:180px;color:#64748b}.value{font-weight:bold}</style></head><body><div class="wrap"><div class="head"><h1>{{ \App\Models\SchoolSetting::current()->name ?? config('app.name') }}</h1><p>Admission Application</p></div><div class="row"><span class="label">Application number</span><span class="value">{{ $application->application_number }}</span></div><div class="row"><span class="label">Admission exam</span><span class="value">{{ $application->exam?->name }}</span></div><div class="row"><span class="label">Applicant name</span><span class="value">{{ $application->applicant_data['full_name_en'] ?? '-' }}</span></div><div class="row"><span class="label">Name in Bangla</span><span class="value">{{ $application->applicant_data['full_name_bn'] ?? '-' }}</span></div><div class="row"><span class="label">Date of birth</span><span class="value">{{ $application->applicant_data['date_of_birth'] ?? '-' }}</span></div><div class="row"><span class="label">Applied class</span><span class="value">{{ $application->schoolClass?->name_en }}</span></div><div class="row"><span class="label">Father / Mother</span><span class="value">{{ $application->applicant_data['father_name'] ?? '-' }} / {{ $application->applicant_data['mother_name'] ?? '-' }}</span></div><div class="row"><span class="label">Guardian phone</span><span class="value">{{ $application->applicant_data['guardian_phone'] ?? '-' }}</span></div><div class="row"><span class="label">Address</span><span class="value">{{ $application->applicant_data['present_address'] ?? '-' }}</span></div></div></body></html>
